class Solution {
public:
    string reverseVowels(string s) {
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
                   c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
        };
        int left = 0;
        int right = (int)s.size() - 1;
        while (left < right) {
            while (left < right && !isVowel(s[left])) left++;
            while (left < right && !isVowel(s[right])) right--;
            if (left < right) {
                char t = s[left];
                s[left] = s[right];
                s[right] = t;
                left++;
                right--;
            }
        }
        return s;
    }
};
